window.BOOK={"key":"shafiidiwan","app":"mutoon-shafiidiwan","lsk":"mutoon_shafiidiwan_v1","prefix":"sh_","title":"مختارات من شعر الشافعي","sub":"الشعر العربي · الإمام الشافعي (ت ٢٠٤هـ) · ٣٢ بيتًا","poems":[{"id":"shafiidiwan","title":"مختارات من شعر الشافعي","nazim":"الإمام محمد بن إدريس الشافعي","death":"ت ٢٠٤هـ","meter":"الوافر والبسيط والطويل","source":"ديوان الإمام الشافعي، شرح عمر فاروق الطباع (دار الأرقم)، مع نص الموسوعة الشعرية المشكول","srcUrl":"https://ketabonline.com/ar/books/102930","note":"خمس مقطوعات مشهورة من «ديوان الإمام الشافعي» (ط. الطباع)، قوبلت كلمةً كلمةً بسكربت بنص الموسوعة الشعرية المشكول (موقع الديوان) وبويكي مصدر، واعتُمد المتداول حيث اختلفت. الديوان جمعٌ متأخر، ونسبة بعض المقطوعات إلى الشافعي لا تثبت بإسناد، والتفصيل في تقرير المصادر.","verses":[["دَعِ الْأَيَّامَ تَفْعَلُ مَا تَشَاءُ","وَطِبْ نَفْسًا إِذَا حَكَمَ الْقَضَاءُ"],["وَلَا تَجْزَعْ لِحَادِثَةِ اللَّيَالِي","فَمَا لِحَوَادِثِ الدُّنْيَا بَقَاءُ"],["وَكُنْ رَجُلًا عَلَى الْأَهْوَالِ جَلْدًا","وَشِيمَتُكَ السَّمَاحَةُ وَالْوَفَاءُ"],["وَإِنْ كَثُرَتْ عُيُوبُكَ فِي الْبَرَايَا","وَسَرَّكَ أَنْ يَكُونَ لَهَا غِطَاءُ"],["تَسَتَّرْ بِالسَّخَاءِ فَكُلُّ عَيْبٍ","يُغَطِّيهِ كَمَا قِيلَ السَّخَاءُ"],["وَلَا تُرِ لِلْأَعَادِي قَطُّ ذُلًّا","فَإِنَّ شَمَاتَةَ الْأَعْدَا بَلَاءُ"],["وَلَا تَرْجُ السَّمَاحَةَ مِنْ بَخِيلٍ","فَمَا فِي النَّارِ لِلظَّمْآنِ مَاءُ"],["وَرِزْقُكَ لَيْسَ يُنْقِصُهُ التَّأَنِّي","وَلَيْسَ يَزِيدُ فِي الرِّزْقِ الْعَنَاءُ"],["وَلَا حُزْنٌ يَدُومُ وَلَا سُرُورٌ","وَلَا بُؤْسٌ عَلَيْكَ وَلَا رَخَاءُ"],["إِذَا مَا كُنْتَ ذَا قَلْبٍ قَنُوعٍ","فَأَنْتَ وَمَالِكُ الدُّنْيَا سَوَاءُ"],["وَمَنْ نَزَلَتْ بِسَاحَتِهِ الْمَنَايَا","فَلَا أَرْضٌ تَقِيهِ وَلَا سَمَاءُ"],["وَأَرْضُ اللَّهِ وَاسِعَةٌ وَلَكِنْ","إِذَا نَزَلَ الْقَضَا ضَاقَ الْفَضَاءُ"],["دَعِ الْأَيَّامَ تَغْدِرُ كُلَّ حِينٍ","فَمَا يُغْنِي عَنِ الْمَوْتِ الدَّوَاءُ"],["شَكَوْتُ إِلَى وَكِيعٍ سُوءَ حِفْظِي","فَأَرْشَدَنِي إِلَى تَرْكِ الْمَعَاصِي"],["وَأَخْبَرَنِي بِأَنَّ الْعِلْمَ نُورٌ","وَنُورُ اللَّهِ لَا يُهْدَى لِعَاصِي"],["مَا فِي الْمَقَامِ لِذِي عَقْلٍ وَذِي أَدَبِ","مِنْ رَاحَةٍ فَدَعِ الْأَوْطَانَ وَاغْتَرِبِ"],["سَافِرْ تَجِدْ عِوَضًا عَمَّنْ تُفَارِقُهُ","وَانْصَبْ فَإِنَّ لَذِيذَ الْعَيْشِ فِي النَّصَبِ"],["إِنِّي رَأَيْتُ وُقُوفَ الْمَاءِ يُفْسِدُهُ","إِنْ سَاحَ طَابَ وَإِنْ لَمْ يَجْرِ لَمْ يَطِبِ"],["وَالْأُسْدُ لَوْلَا فِرَاقُ الْأَرْضِ مَا افْتَرَسَتْ","وَالسَّهْمُ لَوْلَا فِرَاقُ الْقَوْسِ لَمْ يُصِبِ"],["وَالشَّمْسُ لَوْ وَقَفَتْ فِي الْفُلْكِ دَائِمَةً","لَمَلَّهَا النَّاسُ مِنْ عُجْمٍ وَمِنْ عَرَبِ"],["وَالتِّبْرُ كَالتُّرْبِ مُلْقًى فِي أَمَاكِنِهِ","وَالْعُودُ فِي أَرْضِهِ نَوْعٌ مِنَ الْحَطَبِ"],["فَإِنْ تَغَرَّبَ هَذَا عَزَّ مَطْلَبُهُ","وَإِنْ تَغَرَّبَ ذَاكَ عَزَّ كَالذَّهَبِ"],["إِذَا الْمَرْءُ لَا يَرْعَاكَ إِلَّا تَكَلُّفًا","فَدَعْهُ وَلَا تُكْثِرْ عَلَيْهِ التَّأَسُّفَا"],["فَفِي النَّاسِ أَبْدَالٌ وَفِي التَّرْكِ رَاحَةٌ","وَفِي الْقَلْبِ صَبْرٌ لِلْحَبِيبِ وَلَوْ جَفَا"],["فَمَا كُلُّ مَنْ تَهْوَاهُ يَهْوَاكَ قَلْبُهُ","وَلَا كُلُّ مَنْ صَافَيْتَهُ لَكَ قَدْ صَفَا"],["إِذَا لَمْ يَكُنْ صَفْوُ الْوِدَادِ طَبِيعَةً","فَلَا خَيْرَ فِي وِدٍّ يَجِيءُ تَكَلُّفَا"],["وَلَا خَيْرَ فِي خِلٍّ يَخُونُ خَلِيلَهُ","وَيَلْقَاهُ مِنْ بَعْدِ الْمَوَدَّةِ بِالْجَفَا"],["وَيُنْكِرُ عَيْشًا قَدْ تَقَادَمَ عَهْدُهُ","وَيُظْهِرُ سِرًّا كَانَ بِالْأَمْسِ قَدْ خَفَا"],["سَلَامٌ عَلَى الدُّنْيَا إِذَا لَمْ يَكُنْ بِهَا","صَدِيقٌ صَدُوقٌ صَادِقُ الْوَعْدِ مُنْصِفَا"],["نَعِيبُ زَمَانَنَا وَالْعَيْبُ فِينَا","وَمَا لِزَمَانِنَا عَيْبٌ سِوَانَا"],["وَنَهْجُو ذَا الزَّمَانَ بِغَيْرِ ذَنْبٍ","وَلَوْ نَطَقَ الزَّمَانُ لَنَا هَجَانَا"],["وَلَيْسَ الذِّئْبُ يَأْكُلُ لَحْمَ ذِئْبٍ","وَيَأْكُلُ بَعْضُنَا بَعْضًا عِيَانَا"]],"secs":{"1":"دع الأيام تفعل ما تشاء","14":"شكوت إلى وكيع","16":"ما في المقام لذي عقل وذي أدب","23":"إذا المرء لا يرعاك إلا تكلفا","30":"نعيب زماننا والعيب فينا"}}],"sharh":false};
